pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value, uint256 blockTimestamp, uint256 blockNumber) public {
        // Bound the block.timestamp to a realistic range and set it
        blockTimestamp = bound(blockTimestamp, 1, type(uint40).max);
        vm.warp(blockTimestamp);
        // Set block number for deterministic block.number condition
        vm.roll(bound(blockNumber, 0, type(uint64).max));
        // Assume value is exactly 10 ether to meet the require
        vm.assume(value == 10 ether);
        // Deal the contract enough ether to be able to transfer
        vm.deal(address(c), 10 ether);
        // Call the fallback via sending ether
        (bool success, ) = address(c).call{value: value}("");
        // The reference only reverts if block.timestamp <= pastBlockTime
        // But after a successful call, pastBlockTime must equal block.timestamp
        if (success) {
            assertTrue(c.pastBlockTime() == blockTimestamp);
        } else {
            // If reverted, ensure pastBlockTime remains unchanged from previous (but we don't know previous)
            // Since this is fuzz, we just assert the invariants hold for the successful case
            // For the rule to be general, we assert that if the call succeeded, then the rule holds
            // This is already covered above; for revert we assert nothing additional
        }
    }
}

